<?php
require __DIR__.'/bootstrap.php'; require_admin();
$pdo=db();
$members=(int)$pdo->query('SELECT COUNT(*) FROM members')->fetchColumn();
$races=(int)$pdo->query('SELECT COUNT(*) FROM races')->fetchColumn();
$events=(int)$pdo->query('SELECT COUNT(*) FROM clock_events')->fetchColumn();
$pointCount=(int)$pdo->query('SELECT COUNT(*) FROM race_points')->fetchColumn();
$entryCount=(int)$pdo->query("SELECT COUNT(*) FROM race_entries WHERE pigeon_ring IS NOT NULL AND pigeon_ring <> ''")->fetchColumn();
$recent=$pdo->query("SELECT r.*, (SELECT COUNT(*) FROM race_entries e WHERE e.race_id=r.id AND e.pigeon_ring IS NOT NULL AND e.pigeon_ring <> '') AS participants FROM races r ORDER BY r.id DESC LIMIT 8")->fetchAll();
page_header('Overview');
?><div class="grid"><section class="card"><div class="muted">Registered lofts</div><div class="stat"><?=$members?></div><a href="members.php">Manage members →</a></section><section class="card"><div class="muted">Races created</div><div class="stat"><?=$races?></div><a href="races.php">Manage races →</a></section><section class="card"><div class="muted">Race entries</div><div class="stat"><?=$entryCount?></div><a href="race_entries.php">Manage entries →</a></section></div><section class="card"><div class="row"><h2>Race points</h2><a class="btn light" href="race_points.php">Manage points →</a></div><p><strong><?=$pointCount?></strong> saved release locations. Register them once and select a point when creating a race.</p></section><section class="card"><div class="row"><h2>Recent races</h2><a class="btn" href="races.php">+ Create Race</a></div><div class="table-wrap"><table><thead><tr><th>Race</th><th>Release point</th><th>Release time</th><th>Entries</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><a href="results.php?race_id=<?=(int)$r['id']?>"><?=h($r['name'])?></a></td><td><?=h($r['release_location'])?></td><td><?=h(local_time($r['release_at_utc']))?></td><td><?=(int)$r['participants']?></td><td><span class="tag"><?=h($r['status'])?></span></td></tr><?php endforeach; if(!$recent):?><tr><td colspan="5" class="empty">No races yet. Start by registering members and loft coordinates.</td></tr><?php endif;?></tbody></table></div></section><section class="card"><h2>How race speeds are calculated</h2><p>Each race entry uses the member loft coordinate and the race release-point coordinate using the Haversine great-circle formula. Velocity (m/min) = distance (meters) ÷ flight duration (minutes).</p><p class="help">Workflow: register members and lofts → save race points → create a race → register race entries with ring number and barcode → record clocking. The recorded clocking time is when the server receives the clock submission.</p></section><?php page_footer(); ?>
